/**************************************************************************/
/**************************************************************************/
/**                                                                       */
/** ThreadX Test                                                          */
/**                                                                       */
/**   Module execution harness: context saved below a module's stack      */
/**                                                                       */
/**************************************************************************/
/**************************************************************************/

/* A user-mode, memory-protected module moves the stack pointers of two of its
   threads to just above the bottom of memory it may write: the shared area,
   with manager memory below it, and its own data area, with the Module
   Manager's pool below it.  The exception frame fits in the module's memory;
   the rest of the context, r4-r11 and EXC_RETURN (and s16-s31 with the FPU),
   would land below it.  When the threads are preempted, the context switch
   must not write below either region, and each thread must fault when it
   resumes and be terminated.  */

#include "harness_checks.h"

#define MODULE_WAIT_TICKS       ((ULONG) 300UL)
#define PROTECTED_PROPERTIES    ((ULONG) 0x02000007UL)  /* GNU; user mode, memory protection, shared memory */

/* The exception frame: 8 words, or 26 with the FPU's lazily stacked state.  */
#ifdef __ARM_FP
#define FRAME_BYTES             ((ULONG) 104UL)
#else
#define FRAME_BYTES             ((ULONG) 32UL)
#endif

/* Words below each region that the context, s16-s31, r4-r11 and EXC_RETURN,
   would occupy.  */
#define BELOW_WORDS             ((ULONG) 25UL)
#define BELOW_SENTINEL          ((ULONG) 0x5E471E11UL)

extern UCHAR                    module_stack_frame[];

static TXM_MODULE_INSTANCE      test_module;
static ULONG                    data_below[BELOW_WORDS];


/* Count the words below a region that differ from the expected values.  */
static ULONG  changed_words(volatile ULONG *below, const ULONG *expected, ULONG sentinel)
{
ULONG   index;
ULONG   changed;

    changed = 0UL;
    for (index = 0UL; index < BELOW_WORDS; index++)
    {
        if (below[index] != ((expected != TX_NULL) ? expected[index] : sentinel))
        {
            changed++;
        }
    }
    return(changed);
}


VOID  harness_test(VOID)
{
ULONG               available_before;
ULONG               start;
ULONG               index;
volatile ULONG      *data_region_below;
volatile ULONG      *shared_region_below;
TX_THREAD           *frame_thread_0;
TX_THREAD           *frame_thread_1;

    harness_print("Module stack frame: context saved below a module's stack\n");

    available_before = harness_module_pool_available();

    harness_shared_clear();

    harness_expect("memory load", (ULONG) txm_module_manager_memory_load(&test_module, "stack frame",
                                                                         (VOID *) module_stack_frame),
                   (ULONG) TX_SUCCESS);
    harness_expect("module properties", test_module.txm_module_instance_property_flags, PROTECTED_PROPERTIES);

    MODULE_SHARED[MODULE_IN_FRAME_DATA] =   (ULONG) test_module.txm_module_instance_data_start + FRAME_BYTES;
    MODULE_SHARED[MODULE_IN_FRAME_SHARED] = MODULE_SHARED_BASE + FRAME_BYTES;

    /* The words below the data area belong to the Module Manager's pool; those
       below the shared area are unused manager RAM and get sentinels.  */
    data_region_below =   ((volatile ULONG *) test_module.txm_module_instance_data_start) - BELOW_WORDS;
    shared_region_below = MODULE_SHARED - BELOW_WORDS;
    for (index = 0UL; index < BELOW_WORDS; index++)
    {
        data_below[index] =          data_region_below[index];
        shared_region_below[index] = BELOW_SENTINEL;
    }

    harness_expect("shared area grant", (ULONG) harness_shared_grant(&test_module), (ULONG) TX_SUCCESS);
    harness_expect("module start", (ULONG) txm_module_manager_start(&test_module), (ULONG) TX_SUCCESS);

    start = tx_time_get();
    while ((harness_fault_count < 2UL) && ((tx_time_get() - start) < MODULE_WAIT_TICKS))
    {
        tx_thread_sleep(1);
    }

    harness_expect("threads created", MODULE_SHARED[MODULE_OUT_FRAME_STATUS], (ULONG) TX_SUCCESS);
    harness_expect("shared area thread moved its stack", MODULE_SHARED[MODULE_OUT_FRAME_RUNNING_0], 1UL);
    harness_expect("data area thread moved its stack", MODULE_SHARED[MODULE_OUT_FRAME_RUNNING_1], 1UL);

    harness_expect("nothing written below the shared area",
                   changed_words(shared_region_below, TX_NULL, BELOW_SENTINEL), 0UL);
    harness_expect("nothing written below the data area", changed_words(data_region_below, data_below, 0UL), 0UL);

    frame_thread_0 = (TX_THREAD *) MODULE_SHARED[MODULE_OUT_FRAME_THREAD_0];
    frame_thread_1 = (TX_THREAD *) MODULE_SHARED[MODULE_OUT_FRAME_THREAD_1];
    harness_expect("two memory faults reported", harness_fault_count, 2UL);
    harness_expect("fault names the module", (ULONG) harness_fault_module, (ULONG) &test_module);
    harness_expect("shared area thread terminated", (ULONG) frame_thread_0 -> tx_thread_state, (ULONG) TX_TERMINATED);
    harness_expect("data area thread terminated", (ULONG) frame_thread_1 -> tx_thread_state, (ULONG) TX_TERMINATED);

    harness_expect("module stop", (ULONG) txm_module_manager_stop(&test_module), (ULONG) TX_SUCCESS);
    harness_expect("module unload", (ULONG) txm_module_manager_unload(&test_module), (ULONG) TX_SUCCESS);
    harness_expect("module memory returned", harness_module_pool_available(), available_before);
}
